import{_ as t,o as h,c as a,a3 as i}from"./chunks/framework.DX_KL3e0.js";const c="/help/screenshots/tra-cuu/tong-quan.png",p=JSON.parse('{"title":"Tra cứu","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/tra-cuu.md","filePath":"chuc-nang/tra-cuu.md","lastUpdated":1782639524000}'),o={name:"chuc-nang/tra-cuu.md"};function r(g,n,e,u,d,s){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="tra-cuu" tabindex="-1">Tra cứu <a class="header-anchor" href="#tra-cuu" aria-label="Permalink to &quot;Tra cứu&quot;">​</a></h1><p>Module <strong>Tra Cứu</strong> là cổng tìm kiếm và xem thông tin nội bộ của tổ chức: tài sản được cấp cho bạn, văn bản — quyết định, thông báo nội bộ, danh bạ đầu mối liên hệ và lịch sử hoạt động.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tra-cuu</code> (menu <strong>Tra Cứu</strong>, luôn hiện cho mọi người dùng).</li><li><strong>Ai dùng được:</strong> Tất cả nhân sự. Phạm vi dữ liệu tự giới hạn theo bạn (và cấp dưới nếu là quản lý).</li><li><strong>Phân hệ:</strong> Văn Bản · Thông Báo · Tra Cứu Tài Sản · Đầu Mối Liên Hệ · Lịch Sử Hoạt Động.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+c+'" alt="Trang Tra cứu"></p><p>Trang gồm lưới các thẻ dẫn tới từng phân hệ tra cứu:</p><table tabindex="0"><thead><tr><th>Phân hệ</th><th>Đường dẫn</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Văn Bản - Quyết Định</strong></td><td><code>/tra-cuu/van-ban</code></td><td>Xem văn bản, quyết định, thông tư do công ty ban hành.</td></tr><tr><td><strong>Thông Báo - Truyền Thông</strong></td><td><code>/tra-cuu/thong-bao</code></td><td>Đọc bản tin nội bộ từ Phòng Nhân Sự (tự gửi Telegram khi phát hành).</td></tr><tr><td><strong>Tra Cứu Tài Sản</strong></td><td><code>/tra-cuu/tai-san</code></td><td>Xem tài sản bạn phụ trách — gồm Phần cứng, Tên miền, Email, Phần mềm. Phạm vi mở rộng theo vai trò.</td></tr><tr><td><strong>Đầu Mối Liên Hệ</strong></td><td><code>/tra-cuu/dau-moi</code></td><td>Danh sách nhân sự phụ trách từng mảng để liên hệ khi cần.</td></tr><tr><td><strong>Lịch Sử Hoạt Động</strong></td><td><code>/tra-cuu/lich-su</code></td><td>Xem lại việc bạn đã làm, ai giao task, ai nhắc đến bạn.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Ngoài ra</p><p>Nhóm <strong>Dữ Liệu Chấm Công</strong> (<code>/tra-cuu/du-lieu-cong</code>) cũng nằm trong khu vực Tra Cứu nhưng được tách thành tài liệu riêng — xem <a href="/help/chuc-nang/cham-cong.html">Dữ liệu Chấm công</a>.</p></div><h2 id="cac-phan-he" tabindex="-1">Các phân hệ <a class="header-anchor" href="#cac-phan-he" aria-label="Permalink to &quot;Các phân hệ&quot;">​</a></h2><h3 id="van-ban-quyet-đinh" tabindex="-1">Văn Bản - Quyết Định <a class="header-anchor" href="#van-ban-quyet-đinh" aria-label="Permalink to &quot;Văn Bản - Quyết Định&quot;">​</a></h3><p>Tra cứu kho văn bản, quyết định, thông tư công ty đã ban hành. Dùng để xem nội dung và tải tài liệu liên quan công việc.</p><p>Xem chi tiết: <a href="/help/chuc-nang/van-ban-quyet-dinh.html">Văn Bản - Quyết Định</a></p><h3 id="thong-bao-truyen-thong" tabindex="-1">Thông Báo - Truyền Thông <a class="header-anchor" href="#thong-bao-truyen-thong" aria-label="Permalink to &quot;Thông Báo - Truyền Thông&quot;">​</a></h3><p>Bản tin nội bộ do Phòng Nhân Sự phát hành. Khi một thông báo được phát hành, hệ thống tự động gửi kèm qua Telegram.</p><p>Xem chi tiết: <a href="/help/chuc-nang/thong-bao-truyen-thong.html">Thông Báo - Truyền Thông</a></p><h3 id="tra-cuu-tai-san" tabindex="-1">Tra Cứu Tài Sản <a class="header-anchor" href="#tra-cuu-tai-san" aria-label="Permalink to &quot;Tra Cứu Tài Sản&quot;">​</a></h3><p>Xem các tài sản bạn được gán phụ trách. Trang gộp <strong>cả 4 loại tài sản</strong> — Phần cứng, Tên miền, Tài khoản email và Phần mềm — với bộ lọc theo loại, ô tìm kiếm và thẻ tổng quan.</p><p><strong>Phạm vi hiển thị theo vai trò:</strong></p><table tabindex="0"><thead><tr><th>Vai trò</th><th>Thấy được</th></tr></thead><tbody><tr><td><strong>Người dùng</strong></td><td>Tài sản được gán cho chính mình</td></tr><tr><td><strong>Quản lý</strong></td><td>Của mình <strong>+ của cấp dưới</strong> (theo sơ đồ quản lý)</td></tr><tr><td><strong>Admin</strong></td><td><strong>Toàn bộ tài sản công ty</strong> của mình</td></tr><tr><td><strong>Super Admin</strong></td><td><strong>Toàn bộ tài sản hệ thống</strong></td></tr></tbody></table><p>Khi có quyền rộng hơn, giao diện hiện thêm tab thứ hai (&quot;Cấp dưới&quot; / &quot;Toàn công ty&quot; / &quot;Toàn hệ thống&quot;) bên cạnh tab &quot;Của tôi&quot;.</p><p>Đây là chế độ <strong>chỉ xem</strong>; việc cấp phát/chỉnh sửa và gán người phụ trách thực hiện trong module <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a>.</p><div class="tip custom-block"><p class="custom-block-title">Tài sản chỉ hiện khi đã gán người phụ trách</p><p>Một tài sản xuất hiện ở đây khi nó đã được gán <strong>người phụ trách</strong> (hoặc thuộc công ty bạn quản lý). Tài sản cũ chưa gán sẽ không hiện cho tới khi được cập nhật người phụ trách trong Quản lý Tài sản.</p></div><h3 id="đau-moi-lien-he" tabindex="-1">Đầu Mối Liên Hệ <a class="header-anchor" href="#đau-moi-lien-he" aria-label="Permalink to &quot;Đầu Mối Liên Hệ&quot;">​</a></h3><p>Danh bạ nhân sự phụ trách từng mảng (ai liên hệ về việc gì), giúp tìm đúng người khi cần phối hợp.</p><p>Xem chi tiết: <a href="/help/chuc-nang/dau-moi-lien-he.html">Đầu Mối Liên Hệ</a></p><h3 id="lich-su-hoat-đong" tabindex="-1">Lịch Sử Hoạt Động <a class="header-anchor" href="#lich-su-hoat-đong" aria-label="Permalink to &quot;Lịch Sử Hoạt Động&quot;">​</a></h3><p>Dòng thời gian các hoạt động liên quan đến bạn: việc bạn đã thực hiện, task được giao, lần bạn được nhắc đến.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Vì sao tôi chỉ thấy một phần tài sản / dữ liệu?</strong> Tra Cứu tự lọc theo phạm vi của bạn. Quản lý thấy thêm dữ liệu của cấp dưới; người dùng thường chỉ thấy phần của mình.</p><p><strong>Tôi không thấy menu Tra Cứu?</strong> Module này luôn hiển thị cho mọi vai trò. Nếu không thấy, hãy đăng nhập lại hoặc liên hệ Admin.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a> · <a href="/help/chuc-nang/cham-cong.html">Dữ liệu Chấm công</a> · <a href="/help/chuc-nang/lich-su.html">Lịch sử</a></p>',32)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
